<?php
declare(strict_types=1);namespace Atlas\Platform\Resources\Editorial;final class WordPressEditorialQueueRepository implements EditorialQueueRepository{public function __construct(private object$db){}public function findForContext(?string$organizationId,bool$includePlatform,int$limit=50):array{$resources=$this->db->prefix.'atlas_resources';$versions=$this->db->prefix.'atlas_resource_versions';$limit=max(1,min(50,$limit));$scope=$includePlatform?"(r.scope IN ('platform','public') OR (r.scope='organization' AND r.organization_id=%s))":"(r.scope='organization' AND r.organization_id=%s)";$rows=$this->db->get_results($this->db->prepare("SELECT r.id resource_id,r.scope,r.organization_id,v.id version_id,v.title,v.summary,v.review_status,v.version_number,v.created_at FROM `{$resources}` r INNER JOIN `{$versions}` v ON v.resource_id=r.id WHERE {$scope} AND v.review_status IN ('draft','in_review','approved','review_due') ORDER BY FIELD(v.review_status,'in_review','approved','review_due','draft'),v.created_at ASC,v.id ASC LIMIT %d",$organizationId??'',$limit),ARRAY_A);if(!is_array($rows)){return[];}return array_map(static fn(array$r):EditorialQueueItem=>new EditorialQueueItem((string)$r['resource_id'],(string)$r['version_id'],(string)$r['title'],(string)$r['summary'],(string)$r['scope'],$r['organization_id']===null?null:(string)$r['organization_id'],(string)$r['review_status'],(int)$r['version_number'],(string)$r['created_at']),$rows);}}
